01_arithmetic.source:
def first(x):
    a = x + 1
    b = a * 3
    c = b - x
    return c

def second(x):
    a = x + 2
    b = a * 3
    c = b - x
    return c

if __name__ == "__main__":
    for fn in (first, second):
        for value in (0, 1, 3):
            try:
                print(fn(value))
            except Exception as error:
                print(type(error).__name__, str(error))

