exception_handler.source:
def first(rows):
    try:
        value = list(rows)
        size = len(value)
        ratio = 20 // size
        print("first", ratio)
    except ZeroDivisionError:
        print("first empty", value)
    return 1


def second(rows):
    try:
        value = list(rows)
        size = len(value)
        ratio = 30 // size
        print("second", ratio)
    except ZeroDivisionError:
        print("second empty", value)
    finally:
        print("second finally")
    return 2


if __name__ == "__main__":
    first([])
    second([])

