ext_weak_rebound.source:
import weakref
class Target:
    pass


def first(x):
    target = Target()
    backup = target
    watcher = weakref.ref(target)
    target = None
    label = "first"
    print(label, watcher() is not None)
    return watcher() is not None

def second(x):
    target = Target()
    backup = target
    watcher = weakref.ref(target)
    target = None
    label = "second"
    if x:
        print(label, watcher() is not None)
    return watcher() is not None

if __name__ == "__main__":
    for fn in (first, second):
        for value in (0, 1, 3):
            try:
                print(fn(value))
            except Exception as error:
                print(type(error).__name__, str(error))

